const a = Array.from(document.querySelectorAll('a')).find((e) => String(e.getAttribute('href') || '') === '#!/report/download-list');
if (a && typeof a.click === 'function') a.click();
try { location.hash = '#!/report/download-list'; } catch (e) {}
return { ok: true };

const t = (e) => String((e && (e.innerText || e.textContent)) || '').replace(/\s+/g, ' ').trim();
const vis = (e) => { try { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; } catch (err) { return false; } };
const rows = Array.from(document.querySelectorAll('tr')).filter((row) => vis(row) && /生成成功/.test(t(row)) && row.querySelector('input[type=checkbox]'));
if (!rows.length) return { ok: false, error: '下载管理里还没有生成成功的任务' };
const row = rows[0];
const cb = row.querySelector('input[type=checkbox]');
const taskId = String((cb && cb.value) || '');
if (!taskId) return { ok: false, error: '任务行没有 taskId' };
const rowText = t(row);
const m = rowText.match(/(\d{4}-\d{2}-\d{2})至(\d{4}-\d{2}-\d{2})/);
const rangeFrom = (m && m[1]) || '';
const rangeTo = (m && m[2]) || '';
const api = 'https://bpcommon.alimama.com/commonapi/report/async/getDownloadUrl.json?bizCode=universalBP&taskId=' + encodeURIComponent(taskId);
const x1 = new XMLHttpRequest();
x1.open('GET', api, false);
x1.withCredentials = true;
x1.send(null);
let j = {};
try { j = JSON.parse(x1.responseText || '{}'); } catch (err) { return { ok: false, error: 'getDownloadUrl 返回不是 JSON' }; }
const dl = (((j || {}).data || {}).result || {}).downloadUrl || '';
if (!dl) return { ok: false, error: 'getDownloadUrl 没有 downloadUrl', taskId, rowText };
const x2 = new XMLHttpRequest();
x2.open('GET', dl, false);
x2.overrideMimeType('text/plain; charset=x-user-defined');
x2.send(null);
const raw = String(x2.responseText || '');
if (!raw) return { ok: false, error: '下载直链返回空', status: x2.status };
let hex = '';
for (let i = 0; i < raw.length; i += 1) { const c = raw.charCodeAt(i) & 0xff; hex += (c < 16 ? '0' : '') + c.toString(16); }
return {
  ok: true,
  taskId,
  rowText,
  status: x2.status,
  contentType: String(x2.getResponseHeader('content-type') || ''),
  bytes: raw.length,
  filename: 'attachment; filename="营销场景报表_' + (rangeFrom || 'from') + '_' + (rangeTo || 'to') + '.zip"',
  hex,
};
